describe("useWorkspaceStore browser tab to terminal pane drop", () => {
  it("splits the browser tab into an adjacent tab group without merging into terminal pane layout", () => {
    const workspaceServices = services();
    const terminalTargetTab: TerminalTab = {
      kind: "terminal",
      id: "terminal-target",
      label: "Terminal Target",
      sessionId: "session-target",
    };

    const browserSourceTab: BrowserTab = {
      kind: "browser",
      id: "browser-source",
      label: "Browser Source",
      browserId: "browser-1",
      url: "https://example.com",
    };

    const initialState: WorkspaceState = {
      worktrees: [targetWorktree],
      activeWorktreePath: targetWorktree.path,
      sessions: {
        "session-target": terminalSession("session-target", targetWorktree.path),
      },
      layout: {
        tabs: [terminalTargetTab, browserSourceTab],
        activeTabId: "terminal-target",
        tabGroups: {
          "group-default": {
            id: "group-default",
            tabIds: [terminalTargetTab.id, browserSourceTab.id],
            activeTabId: terminalTargetTab.id,
          },
        },
        tabGroupLayout: { type: "group", groupId: "group-default" },
        focusedGroupId: "group-default",
        layoutsByTabId: {
          [terminalTargetTab.id]: {
            root: { type: "leaf", leafId: "leaf-target" },
            activeLeafId: "leaf-target",
            expandedLeafId: null,
            sessionIdsByLeafId: { "leaf-target": "session-target" },
          },
        },
      },
      unreadTabIds: {},
      unreadWorktreePaths: {},
      activityBySessionId: {},
    };

    const { result } = renderHook(() =>
      useWorkspaceStore({ initialWorktrees: [targetWorktree], services: workspaceServices }),
    );

    act(() => result.current.restoreWorkspace(initialState));

    const targetGroupId = "group-default";
    act(() =>
      result.current.moveTabToSplit("browser-source", targetGroupId, "horizontal", "second", {
        tabId: "terminal-target",
        leafId: "leaf-target",
      }),
    );

    // Tab membership assertions: browser is moved into its own tab group split
    const targetGroup = groupForTab(result.current.state, "terminal-target");
    const sourceGroup = groupForTab(result.current.state, "browser-source");

    expect(targetGroup).toBeDefined();
    expect(sourceGroup).toBeDefined();
    expect(sourceGroup?.id).not.toBe(targetGroup?.id);
    expect(targetGroup?.tabIds).toEqual(["terminal-target"]);
    expect(sourceGroup?.tabIds).toEqual(["browser-source"]);

    // Two-layer tab group layout split
    expect(result.current.state.layout.tabGroupLayout).toMatchObject({
      type: "split",
      direction: "horizontal",
      first: { type: "group", groupId: targetGroup?.id },
      second: { type: "group", groupId: sourceGroup?.id },
    });

    // Browser tab remains exactly once in the workspace and retains metadata
    const browserTabs = result.current.state.layout.tabs.filter((tab) => tab.id === "browser-source");
    expect(browserTabs).toHaveLength(1);
    expect(browserTabs[0]).toEqual(browserSourceTab);

    // Terminal target pane layout remains unchanged (NOT merged into TabPaneLayout)
    const targetLayout = result.current.state.layout.layoutsByTabId["terminal-target"];
    expect(targetLayout.root).toEqual({ type: "leaf", leafId: "leaf-target" });
    expect(targetLayout.sessionIdsByLeafId).toEqual({ "leaf-target": "session-target" });

    // Focus / active state
    expect(result.current.state.layout.activeTabId).toBe("browser-source");
    expect(result.current.state.layout.focusedGroupId).toBe(sourceGroup?.id);

    // Backend / PTY assertions: no spawning or killing terminals
    expect(result.current.state.sessions["session-target"]).toBeDefined();
    expect(workspaceServices.spawnTerminal).not.toHaveBeenCalled();
    expect(workspaceServices.closeTerminal).not.toHaveBeenCalled();
  });
});

import type { PaneDirection } from "../../state/paneTree";

export type TabDropEdge = "left" | "right" | "top" | "bottom";

export type TabDragData = {
  type: "tab";
  tabId: string;
  groupId: string;
  index: number;
};

export type PaneDragData = {
  type: "pane";
  tabId: string;
  sourcePaneId?: string;
  sourceSessionId?: string;
  leafId?: string;
};

export type GroupBodyDropData = {
  type: "group-body";
  groupId: string;
};

export type GroupEdgeDropData = {
  type: "group-edge";
  groupId: string;
  edge: TabDropEdge;
};

export type PaneLeafDropData = {
  type: "pane-leaf";
  tabId: string;
  leafId: string;
};

export type PaneEdgeDropData = {
  type: "pane-edge";
  tabId: string;
  leafId: string;
  edge: TabDropEdge;
};

export type WorkspaceDragData = TabDragData | PaneDragData;
export type WorkspaceDropData = TabDragData | GroupBodyDropData | GroupEdgeDropData | PaneLeafDropData | PaneEdgeDropData;

export type WorkspaceDropCommand =
  | {
      type: "move-tab-to-group";
      tabId: string;
      targetGroupId: string;
      targetIndex?: number;
    }
  | {
      type: "move-tab-to-split";
      tabId: string;
      targetGroupId: string;
      direction: PaneDirection;
      position: "first" | "second";
    }
  | {
      type: "move-tab-to-pane-split";
      sourceTabId: string;
      targetTabId: string;
      targetLeafId: string;
      direction: PaneDirection;
      position: "first" | "second";
    }
  | {
      type: "move-pane-to-pane-split";
      sourceTabId: string;
      sourceLeafId: string;
      targetTabId: string;
      targetLeafId: string;
      direction: PaneDirection;
      position: "first" | "second";
    }
  | {
      type: "detach-pane-to-tab";
      sourceTabId: string;
      leafId: string;
      targetGroupId: string;
      targetIndex?: number;
    }
  | {
      type: "swap-panes";
      tabId: string;
      sourceLeafId: string;
      targetLeafId: string;
    };

export function isWorkspaceDragData(value: unknown): value is WorkspaceDragData {
  if (!value || typeof value !== "object") return false;
  if (!("type" in value)) return false;
  const type = value.type;
  if (type === "tab") {
    return (
      "tabId" in value &&
      typeof value.tabId === "string" &&
      "groupId" in value &&
      typeof value.groupId === "string" &&
      "index" in value &&
      typeof value.index === "number"
    );
  }
  if (type === "pane") {
    return (
      "tabId" in value &&
      typeof value.tabId === "string" &&
      (("sourcePaneId" in value && typeof value.sourcePaneId === "string") ||
        ("leafId" in value && typeof value.leafId === "string"))
    );
  }
  return false;
}

export function isWorkspaceDropData(value: unknown): value is WorkspaceDropData {
  if (!value || typeof value !== "object") return false;
  if (!("type" in value)) return false;
  const type = value.type;
  switch (type) {
    case "tab":
      return (
        "tabId" in value &&
        typeof value.tabId === "string" &&
        "groupId" in value &&
        typeof value.groupId === "string" &&
        "index" in value &&
        typeof value.index === "number"
      );
    case "group-body":
      return "groupId" in value && typeof value.groupId === "string";
    case "group-edge":
      return "groupId" in value && typeof value.groupId === "string" && "edge" in value && isTabDropEdge(value.edge);
    case "pane-leaf":
      return "tabId" in value && typeof value.tabId === "string" && "leafId" in value && typeof value.leafId === "string";
    case "pane-edge":
      return (
        "tabId" in value &&
        typeof value.tabId === "string" &&
        "leafId" in value &&
        typeof value.leafId === "string" &&
        "edge" in value &&
        isTabDropEdge(value.edge)
      );
    default:
      return false;
  }
}

export function resolveWorkspaceDropCommand(
  active: WorkspaceDragData,
  over: WorkspaceDropData | null,
): WorkspaceDropCommand | null {
  if (!over) return null;

  if (active.type === "tab") {
    switch (over.type) {
      case "pane-edge": {
        const { direction, position } = edgeToSplit(over.edge);
        return {
          type: "move-tab-to-pane-split",
          sourceTabId: active.tabId,
          targetTabId: over.tabId,
          targetLeafId: over.leafId,
          direction,
          position,
        };
      }
      case "group-edge": {
        const { direction, position } = edgeToSplit(over.edge);
        return {
          type: "move-tab-to-split",
          tabId: active.tabId,
          targetGroupId: over.groupId,
          direction,
          position,
        };
      }
      case "tab":
        if (over.tabId === active.tabId && over.groupId === active.groupId) return null;
        return {
          type: "move-tab-to-group",
          tabId: active.tabId,
          targetGroupId: over.groupId,
          targetIndex: over.index,
        };
      case "group-body":
        return {
          type: "move-tab-to-group",
          tabId: active.tabId,
          targetGroupId: over.groupId,
        };
      case "pane-leaf":
        return null;
    }
  }

  if (active.type === "pane") {
    const sourceLeafId = active.sourcePaneId ?? active.leafId ?? "";
    switch (over.type) {
